#!/usr/bin/env bash
# Disposable PG17 only. No remote URI, host ports or real user data.
# Verifies 20261120_db_reorg_p6b1q_free_model_contract.sql as a NON-superuser:
# - report_chat_first_token / validate_managed_config_value start as the production bodies (md5 checked);
# - refuses (changing nothing) while the catalog still has a free model, or quota decisions were written recently;
# - patches both functions to the expected md5, retires the two keys, drops 3 functions and both quota tables;
# - the patched validator rejects the retired keys and still validates other keys; rerun is a no-op.
set -euo pipefail
task_root="$(cd "$(dirname "$0")/.." && pwd)"
migration="$task_root/packages/shared/migrations/20261120_db_reorg_p6b1q_free_model_contract.sql"
task_container="st-db-reorg-p6b1q-contract-${RANDOM}-$$"
trap 'docker rm -f "$task_container" >/dev/null 2>&1 || true' EXIT
docker run -d --rm --name "$task_container" --network none -e POSTGRES_HOST_AUTH_METHOD=trust postgres:17 >/dev/null
for _ in $(seq 1 60); do
  if [[ "$(docker logs "$task_container" 2>&1)" == *'PostgreSQL init process complete'* ]] &&
    docker exec "$task_container" pg_isready -U postgres >/dev/null 2>&1; then break; fi
  sleep 1
done
docker exec -i "$task_container" psql -X -q -U postgres -v ON_ERROR_STOP=1 >/dev/null <<'SQL'
CREATE ROLE app_admin LOGIN NOSUPERUSER CREATEROLE;
CREATE DATABASE fixture OWNER app_admin;
SQL
psql_f() { docker exec -i "$task_container" psql -X -q -U app_admin -d fixture -v ON_ERROR_STOP=1 "$@"; }
check() { # label; SQL on stdin must print exactly "t"
  local got
  got=$(psql_f -At)
  if [[ "$got" != "t" ]]; then echo "FAIL: $1 (got: $got)"; exit 1; fi
  echo "ok: $1"
}
# Production bodies (base64 of pg_proc.prosrc, 11-20)
REPORT_B64=''
VALIDATE_B64=''
setup() { # $1 = clean | free_model | recent
  psql_f >/dev/null <<'SQL'
DROP SCHEMA IF EXISTS app_core, billing, experience, admin CASCADE;
CREATE SCHEMA app_core; CREATE SCHEMA billing; CREATE SCHEMA experience; CREATE SCHEMA admin;
CREATE TABLE app_core.runtime_config (key text PRIMARY KEY, value jsonb);
CREATE TABLE admin.managed_config_keys (config_key text PRIMARY KEY, retired_at timestamptz);
CREATE FUNCTION admin.is_managed_config_key(p_key text) RETURNS boolean LANGUAGE sql STABLE AS
  $$ SELECT EXISTS (SELECT 1 FROM admin.managed_config_keys WHERE config_key = p_key AND retired_at IS NULL) $$;
CREATE FUNCTION admin.validate_free_quota_exhausted_dialog_config(p_value jsonb) RETURNS void LANGUAGE plpgsql AS
  $$ BEGIN IF p_value ->> 'free_quota_exhausted' IS NULL THEN RETURN; END IF; END $$;
CREATE TABLE experience.chat_history (id uuid PRIMARY KEY, llm_charge_id uuid, user_id uuid, session_id uuid, revision int);
CREATE TABLE experience.chat_generation_requests (
  chat_history_id uuid PRIMARY KEY, client_request_id uuid, measurement_method text, client_outcome text,
  recoverable_delivery boolean, requires_visible_token boolean, first_token_deadline_ms numeric,
  client_delivery_failed boolean, client_first_token_visible_ms numeric, client_reason text);
CREATE TABLE billing.character_free_chat_quotas (user_id uuid, character_id uuid, used_rounds int, PRIMARY KEY (user_id, character_id));
CREATE TABLE billing.character_free_chat_quota_decisions (
  charge_key uuid PRIMARY KEY, status text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION billing.reserve_character_free_chat_round(p_charge uuid, p_user uuid, p_character uuid, p_limit integer)
  RETURNS void LANGUAGE plpgsql AS $$ BEGIN INSERT INTO billing.character_free_chat_quota_decisions VALUES (p_charge, 'reserved'); END $$;
CREATE FUNCTION billing.finalize_character_free_chat_round(p_charge uuid, p_success boolean)
  RETURNS void LANGUAGE plpgsql AS $$ BEGIN UPDATE billing.character_free_chat_quota_decisions SET status = 'released' WHERE charge_key = p_charge; END $$;
INSERT INTO admin.managed_config_keys VALUES
  ('miniapp_character_free_chat_quota_limit', NULL), ('miniapp_free_quota_exhausted_dialog_config', NULL),
  ('miniapp_new_user_signup_bonus_credits', NULL);
INSERT INTO app_core.runtime_config VALUES
  ('miniapp_character_free_chat_quota_limit', '40'), ('miniapp_free_quota_exhausted_dialog_config', '{"text":"x"}'),
  ('miniapp_new_user_signup_bonus_credits', '5'),
  ('llm_model_catalog', '{"tiers":[{"models":[{"id":"flash","is_free":false},{"id":"pro"}]}]}');
INSERT INTO billing.character_free_chat_quotas VALUES (gen_random_uuid(), gen_random_uuid(), 3);
INSERT INTO billing.character_free_chat_quota_decisions VALUES
  (gen_random_uuid(), 'reserved', now() - interval '25 days', now() - interval '25 days'),
  (gen_random_uuid(), 'consumed', now() - interval '25 days', now() - interval '25 days');
SQL
  { printf '%s' "CREATE FUNCTION experience.report_chat_first_token(p_user_id uuid, p_session_id uuid, p_report jsonb) RETURNS boolean LANGUAGE plpgsql SET search_path TO 'pg_catalog' AS \$prodfn\$"
    echo "$REPORT_B64" | base64 -d
    printf '%s\n' '$prodfn$;'
    printf '%s' "CREATE FUNCTION admin.validate_managed_config_value(p_config_key text, p_value jsonb, p_text_value text) RETURNS void LANGUAGE plpgsql STABLE SET search_path TO 'pg_catalog' AS \$prodfn\$"
    echo "$VALIDATE_B64" | base64 -d
    printf '%s\n' '$prodfn$;'; } | psql_f >/dev/null
  case "$1" in
    free_model) psql_f -c "UPDATE app_core.runtime_config SET value = '{\"tiers\":[{\"models\":[{\"id\":\"flash\",\"is_free\":true}]}]}' WHERE key = 'llm_model_catalog'" >/dev/null ;;
    recent) psql_f -c "UPDATE billing.character_free_chat_quota_decisions SET updated_at = now() WHERE status = 'consumed'" >/dev/null ;;
  esac
}
unchanged() {
  check "$1: nothing changed" <<'SQL'
SELECT to_regclass('billing.character_free_chat_quota_decisions') IS NOT NULL
   AND (SELECT md5(prosrc) FROM pg_proc WHERE proname = 'report_chat_first_token') = 'ecdab7e19b7ad4868d5f0a074a1553d8'
   AND (SELECT count(*) FROM admin.managed_config_keys WHERE retired_at IS NOT NULL) = 0;
SQL
}

setup clean
check 'fixtures are the production bodies' <<'SQL'
SELECT (SELECT md5(prosrc) FROM pg_proc WHERE proname = 'report_chat_first_token') = 'ecdab7e19b7ad4868d5f0a074a1553d8'
   AND (SELECT md5(prosrc) FROM pg_proc WHERE proname = 'validate_managed_config_value') = '950822be56d6075c4d633c3e7f1d9856';
SQL

setup free_model
if out=$(psql_f <"$migration" 2>&1); then echo "FAIL: free model should refuse"; exit 1; fi
[[ "$out" == *'1 free models are still in llm_model_catalog'* ]] || { echo "FAIL: free model message: $out"; exit 1; }
unchanged 'free model in catalog refuses'

setup recent
if out=$(psql_f <"$migration" 2>&1); then echo "FAIL: recent write should refuse"; exit 1; fi
[[ "$out" == *'1 quota decisions written in the last hour'* ]] || { echo "FAIL: recent message: $out"; exit 1; }
unchanged 'recent quota write refuses'

setup clean
out=$(psql_f <"$migration" 2>&1)
[[ "$out" == *'2 functions no longer reference the free quota'* && "$out" == *'2 keys retired, 2 runtime_config rows deleted'* &&
   "$out" == *'(1 quota rows, 2 decisions, 1 still reserved) and 3 functions'* ]] || { echo "FAIL: apply: $out"; exit 1; }
echo 'ok: applied'
check 'functions patched to the expected md5 with no quota reference left' <<'SQL'
SELECT (SELECT md5(prosrc) FROM pg_proc WHERE proname = 'report_chat_first_token') = '4351ecbbe18b2b0355e17e3fddbd1717'
   AND (SELECT md5(prosrc) FROM pg_proc WHERE proname = 'validate_managed_config_value') = '41fc722cb156ed82fb511b9db5ab2cf4'
   AND NOT EXISTS (SELECT 1 FROM pg_proc WHERE prosrc ~ '(free_chat_quota|free_chat_round|free_quota_exhausted_dialog)');
SQL
check 'tables and quota functions dropped; keys retired; config rows deleted' <<'SQL'
SELECT to_regclass('billing.character_free_chat_quota_decisions') IS NULL
   AND to_regclass('billing.character_free_chat_quotas') IS NULL
   AND NOT EXISTS (SELECT 1 FROM pg_proc WHERE proname IN ('reserve_character_free_chat_round', 'finalize_character_free_chat_round',
                                                          'validate_free_quota_exhausted_dialog_config'))
   AND (SELECT count(*) FROM admin.managed_config_keys WHERE retired_at IS NOT NULL) = 2
   AND NOT EXISTS (SELECT 1 FROM app_core.runtime_config WHERE key IN ('miniapp_character_free_chat_quota_limit', 'miniapp_free_quota_exhausted_dialog_config'));
SQL
if out=$(psql_f -c "SELECT admin.validate_managed_config_value('miniapp_character_free_chat_quota_limit', '40', NULL)" 2>&1); then
  echo "FAIL: retired key should be rejected"; exit 1; fi
[[ "$out" == *'config key is not managed by admin'* ]] || { echo "FAIL: retired message: $out"; exit 1; }
echo 'ok: retired key rejected by the patched validator'
psql_f -c "SELECT admin.validate_managed_config_value('miniapp_new_user_signup_bonus_credits', '5', NULL)" >/dev/null
if psql_f -c "SELECT admin.validate_managed_config_value('miniapp_new_user_signup_bonus_credits', '-1', NULL)" >/dev/null 2>&1; then
  echo "FAIL: other keys must still validate"; exit 1; fi
echo 'ok: other keys still validate'
out=$(psql_f <"$migration" 2>&1)
[[ "$out" == *'0 functions no longer reference'* && "$out" == *'0 keys retired, 0 runtime_config rows deleted'* &&
   "$out" == *'free quota tables already dropped'* ]] || { echo "FAIL: rerun: $out"; exit 1; }
echo 'ok: rerun is a no-op'
echo 'all checks passed'
